// Content with portions generated by generative AI platform
package org.eclipse.kura.core.data.transport.mqtt;

import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import org.eclipse.kura.data.transport.listener.DataTransportListener;
import org.junit.Test;
import org.osgi.service.component.ComponentContext;

public class NotifyDataTransportListenersTest {

    private static final String TOPIC = "topic";
    private static final byte[] PAYLOAD = new byte[] { 1, 2, 3 };

    private final ComponentContext componentContext = mock(ComponentContext.class);
    private final DataTransportListenerS dataTransportListeners = new DataTransportListenerS(this.componentContext);
    private final org.eclipse.kura.data.DataTransportListener failingService = mock(
            org.eclipse.kura.data.DataTransportListener.class);
    private final org.eclipse.kura.data.DataTransportListener healthyService = mock(
            org.eclipse.kura.data.DataTransportListener.class);
    private final DataTransportListener failingListener = mock(DataTransportListener.class);
    private final DataTransportListener healthyListener = mock(DataTransportListener.class);
    private Throwable propagatedThrowable;

    /*
     * Scenarios
     */

    @Test
    public void notifiesServicesAndListeners() {
        givenRegisteredServices(this.healthyService);
        givenAddedListeners(this.healthyListener);

        whenMessageArrives();

        thenNothingPropagated();
        thenServiceNotifiedOfMessage(this.healthyService);
        thenListenerNotifiedOfMessage(this.healthyListener);
    }

    @Test
    public void notifiesRemainingServicesAndListenersWhenOneThrowsException() {
        givenServiceFailingWith(this.failingService, new IllegalStateException("listener failure"));
        givenListenerFailingWith(this.failingListener, new IllegalStateException("listener failure"));
        givenRegisteredServices(this.failingService, this.healthyService);
        givenAddedListeners(this.failingListener, this.healthyListener);

        whenMessageArrives();

        thenNothingPropagated();
        thenServiceNotifiedOfMessage(this.healthyService);
        thenListenerNotifiedOfMessage(this.healthyListener);
    }

    @Test
    public void notifiesRemainingServicesAndListenersWhenOneFailsWithLinkageError() {
        givenServiceFailingWith(this.failingService, new NoClassDefFoundError("uninstalled bundle class"));
        givenListenerFailingWith(this.failingListener, new NoClassDefFoundError("uninstalled bundle class"));
        givenRegisteredServices(this.failingService, this.healthyService);
        givenAddedListeners(this.failingListener, this.healthyListener);

        whenMessageArrives();

        thenNothingPropagated();
        thenServiceNotifiedOfMessage(this.healthyService);
        thenListenerNotifiedOfMessage(this.healthyListener);
    }

    @Test
    public void propagatesVirtualMachineErrorFromListener() {
        givenListenerFailingWith(this.failingListener, new OutOfMemoryError("simulated"));
        givenRegisteredServices();
        givenAddedListeners(this.failingListener, this.healthyListener);

        whenMessageArrives();

        thenPropagated(OutOfMemoryError.class);
    }

    /*
     * Steps
     */

    private void givenRegisteredServices(org.eclipse.kura.data.DataTransportListener... services) {
        when(this.componentContext.locateServices("DataTransportListener")).thenReturn(services);
    }

    private void givenAddedListeners(DataTransportListener... listeners) {
        for (final DataTransportListener listener : listeners) {
            this.dataTransportListeners.add(listener);
        }
    }

    private void givenServiceFailingWith(org.eclipse.kura.data.DataTransportListener service, Throwable failure) {
        doThrow(failure).when(service).onMessageArrived(TOPIC, PAYLOAD, 1, false);
    }

    private void givenListenerFailingWith(DataTransportListener listener, Throwable failure) {
        doThrow(failure).when(listener).onMessageArrived(TOPIC, PAYLOAD, 1, false);
    }

    private void whenMessageArrives() {
        try {
            this.dataTransportListeners.onMessageArrived(TOPIC, PAYLOAD, 1, false);
        } catch (Throwable e) {
            this.propagatedThrowable = e;
        }
    }

    private void thenNothingPropagated() {
        assertNull(this.propagatedThrowable);
    }

    private void thenPropagated(Class<? extends Throwable> expected) {
        assertTrue("unexpected: " + this.propagatedThrowable, expected.isInstance(this.propagatedThrowable));
    }

    private void thenServiceNotifiedOfMessage(org.eclipse.kura.data.DataTransportListener service) {
        verify(service).onMessageArrived(TOPIC, PAYLOAD, 1, false);
    }

    private void thenListenerNotifiedOfMessage(DataTransportListener listener) {
        verify(listener).onMessageArrived(TOPIC, PAYLOAD, 1, false);
    }
}
